<?php

namespace App\Http\Controllers\Configuraciones;

use Exception;
use Illuminate\Http\Request;
use Illuminate\Http\JsonResponse;
use Illuminate\Support\Facades\DB;
use App\Http\Controllers\Controller;
use Illuminate\Http\Response as HttpResponse;
use Symfony\Component\HttpFoundation\{Response};
use App\Http\Services\Configuraciones\ArchivoService;
use App\Http\Repositories\Configuraciones\ArchivoRepository;

class ArchivoController extends Controller
{
    /**
     * Constructor.
     *
     * @param ArchivoService $servicio Servicio de archivos.
     * @param ArchivoRepository $repositorio Repositorio de archivos.
     * @return void
     * @author Daniel Beltrán
     */
    public function __construct(private ArchivoService $servicio, private ArchivoRepository $repositorio) {}

    /**
     * Obtener el listado de archivos.
     *
     * @param Request $request Contenido de la petición.
     * @return JsonResponse
     * @author Daniel Beltrán
     */
    public function listado(Request $request) {
        return new JsonResponse([
            'data' => $this->repositorio->getTodo($request)
        ], 200);
    }

    /**
     * Abrir un archivo.
     *
     * @param int $id ID del archivo.
     * @return Response
     * @author Daniel Beltrán
     */
    public function abrir(int $id): Response {
        return $this->servicio->abrir($id);
    }

    /**
     * Obtener un archivo.
     *
     * @param Request $request Contenido de la petición.
     * @return JsonResponse
     * @author Daniel Beltrán
     */
    public function obtenerUno(Request $request): JsonResponse {
        return new JsonResponse([
            'data' => $this->repositorio->getUnoAvanzado($request)
        ], 200);
    }

    /**
     * Eliminar un archivo.
     *
     * @param int $id ID del archivo.
     * @return JsonResponse
     * @author Daniel Beltrán
     */
    public function destroy(int $id): JsonResponse {
        $codigo    = HttpResponse::HTTP_OK;
        $respuesta = [
            'message' => 'Archivo eliminado correctamente'
        ];

        try {
            DB::beginTransaction();
            $this->servicio->eliminar($id);
            DB::commit();
        } catch (Exception $error) {
            DB::rollBack();

            $codigo    = HttpResponse::HTTP_BAD_REQUEST;
            $respuesta = [
                'message' => 'Ocurrió un error',
                'errors'  => $error->getMessage()
            ];
        }

        return new JsonResponse($respuesta, $codigo);
    }
}
