<?php

namespace App\Http\Services\Configuraciones;

use App\Traits\ArchivoTrait;
use Illuminate\Http\Request;
use App\Http\Services\BaseService;
use Symfony\Component\HttpFoundation\{Response};
use App\Http\Repositories\Configuraciones\ArchivoRepository;

/**
 * @property ArchivoRepository $repositorio
 */
class ArchivoService extends BaseService
{
    use ArchivoTrait;

    /**
     * Constructor.
     *
     * @param ArchivoRepository $repositorio Repositorio de archivos.
     * @return void
     * @author Daniel Beltrán
     */
    public function __construct(ArchivoRepository $repositorio) {
        parent::__construct($repositorio);
    }

    /**
     * Guardar varios archivos.
     *
     * @param string $modelo Modelo al que pertenecen los archivos.
     * @param int $id ID del modelo.
     * @param array $archivos Archivos a guardar.
     * @param string $carpeta Carpeta donde se guardarán los archivos (tiene que estar dentro de 'private/archivos/').
     * @param bool $conservar_nombre_original Indica si se conservará el nombre original de los archivos.
     * @param ?bool $incluir_id_en_carpeta Indica si debe generarse un directorio adicional con el ID del modelo.
     * @return void
     * @author Daniel Beltrán
     * @author Andres Gonzalez
     */
    public function guardarVarios(string $modelo, int $id, array $archivos, string $carpeta, bool $conservar_nombre_original = false, ?bool $incluir_id_en_carpeta = true): void {
        $ruta = "private/archivos/{$carpeta}";

        if ($incluir_id_en_carpeta) {
            $ruta .= "/{$id}";
        }

        $this->generarDirectorios("app/{$ruta}");

        foreach ($archivos as $llave => $archivo) {
            $nombre_original = str_replace('_', '-', $llave) . date('YmdHis') . '.' . $archivo->getClientOriginalExtension();
            $nombre_archivo  = $this->generarNombreArchivo($archivo);
            $this->guardarArchivoEnRuta($archivo, $ruta, $nombre_archivo);

            $this->repositorio->crear([
                'modelo'                  => $modelo,
                'modelo_id'               => $id,
                'nombre'                  => $llave,
                'nombre_original_archivo' => $conservar_nombre_original ? $archivo->getClientOriginalName() : null,
                'ruta'                    => $ruta . '/' . $nombre_archivo
            ]);
        }
    }

    /**
     * Guardar varios archivos en base64.
     *
     * @param string $modelo Modelo al que pertenecen los archivos.
     * @param int $id ID del modelo.
     * @param array $archivos Archivos a guardar.
     * @param string $carpeta Carpeta donde se guardarán los archivos (tiene que estar dentro de 'private/archivos/').
     * @param bool $conservar_nombre_original Indica si se conservará el nombre original de los archivos.
     * @return void
     * @author Daniel Beltrán
     */
    public function guardarVariosBase64(string $modelo, int $id, array $archivos, string $carpeta, bool $conservar_nombre_original = false): void {
        $this->generarDirectorios("app/private/archivos/{$carpeta}/{$id}");
        $ruta = "private/archivos/{$carpeta}/{$id}";

        foreach ($archivos as $llave => $valor) {
            if ($conservar_nombre_original) {
                $nombre_archivo = $this->guardarArchivoBase64EnRuta($valor, $ruta, str_replace('_', '-', $llave) . date('YmdHis'));
            } else {
                $nombre_archivo = $this->guardarArchivoBase64EnRuta($valor, $ruta);
            }

            $this->repositorio->crear([
                'modelo'    => $modelo,
                'modelo_id' => $id,
                'nombre'    => $llave,
                'ruta'      => $ruta . '/' . $nombre_archivo
            ]);
        }
    }

    /**
     * Abrir un archivo.
     *
     * @param int $id ID del archivo.
     * @return Response
     * @author Daniel Beltrán
     */
    public function abrir(int $id): Response {
        $archivo = $this->repositorio->getUno($id);
        return $this->obtenerArchivoDesdeRuta($archivo->ruta);
    }

    /**
     * Eliminar un archivo.
     *
     * @param int $id ID del archivo.
     * @return void
     * @author Daniel Beltrán
     */
    public function eliminar(int $id): void {
        $archivo = $this->repositorio->getUno($id);
        $this->eliminarArchivoDesdeRuta($archivo->ruta);
        $this->repositorio->eliminar($id);
    }

    /**
     * Eliminar todos los archivos de un modelo.
     *
     * @param string $modelo Modelo al que pertenecen los archivos.
     * @param int $id ID del modelo.
     * @param ?string $nombre Nombre del tipo de archivo.
     * @return void
     * @author Daniel Beltrán
     */
    public function eliminarPorModelo(string $modelo, int $id, ?string $nombre = null): void {
        $archivos = $this->repositorio->getTodo(new Request([
            'modelo'    => $modelo,
            'modelo_id' => $id,
            'nombre'    => $nombre
        ]));

        if (!is_null($archivos)) {
            foreach ($archivos as $archivo) {
                $this->eliminarArchivoDesdeRuta($archivo->ruta);
                $this->repositorio->eliminar($archivo->id);
            }
        }
    }
}
```

