        ->when($request->filled('modelo'), fn($consulta) => $consulta->where('modelo', $request->modelo))
        ->when($request->filled('modelo_id'), fn($consulta) => $consulta->where('modelo_id', $request->modelo_id))
        ->when($request->filled('nombre'), fn($consulta) => $consulta->where('nombre', $request->nombre))
        ->when($request->filled('ruta'), fn($consulta) => $consulta->whereLike('ruta', "%{$request->ruta}%"))
        ->first();
