```php
<?php

namespace App\Http\Repositories\OfertasLaborales;

use Illuminate\Http\Request;
use Illuminate\Support\Collection;
use App\Http\Repositories\BaseRepository;
use App\Models\OfertasLaborales\Comentario;

class ComentarioRepository extends BaseRepository
{
    /**
     * Constructor.
     *
     * @param Comentario $modelo Modelo comentario.
     * @return void
     * @author Fahibram Cárcamo
     */
    public function __construct(Comentario $modelo) {
        parent::__construct($modelo);
    }

    /**
     * Obtener todos los comentarios.
     *
     * @param Request $request Contenido de la petición.
     * @return Collection
     */
    public function getTodo(Request $request): Collection {
        return $this->modelo::select('id', 'modelo_id', 'modelo_type', 'usuario_id', 'contenido', 'created_at')
            ->with('usuario:id,nombres,apellidos')
            ->when($request->filled('modelo_type'), fn($consulta) => $consulta->where('modelo_type', $request->modelo_type))
            ->when($request->filled('modelo_id'), fn($consulta) => $consulta->where('modelo_id', $request->modelo_id))
            ->orderBy('created_at', 'DESC')
            ->get();
    }
}
```

**Cambios vs el actual:** Se agrega el método `getTodo` con filtros por `modelo_type` y `modelo_id`, cargando la relación `usuario`. Se elimina `cargarRelacionesComentarios` (ya no se necesita, se usa `load` directo en el servicio).

