function mostrarSeccionComentarios(comentarios, tipo_comentario) {
    return comentarios && comentarios.length > 0 ? `
        <div class="row align-items-center mb-5">
            <div class="col-auto text-headline-5 text-gray-10 fw-bold">
                Comentarios
            </div>
            <div class="col-auto py-1 px-3 bg-gray-90 rounded-4">${comentarios.length}</div>
        </div>
        <div class="rounded-4 pt-6 pb-1 px-4 bg-gray-90" id="contenedor-comentarios-${tipo_comentario}">
            ${comentarios.map(comentario => mostrarComentario(comentario)).join('')}
        </div>
    ` : '';
}

/**
 * Mostrar un comentario en la sección de comentarios de la prueba técnica.
 *
 * @param {Object} comentario Objeto del comentario.
 * @returns {string} Código HTML del comentario.
 * @author José Manuel Jiménez
 * @author Andres Gonzalez
 */
function mostrarComentario(comentario) {
    // Crear elemento temporal para insertar HTML de forma segura
    let elemento_temporal = document.createElement('div');
    elemento_temporal.innerHTML = comentario.comentario || '';

    return `
        <div class="row mb-5">
            <div class="col-auto">
                <img src="/usuarios-imagen/${comentario.usuario_id}" class="rounded-circle border" width="50" height="50">
            </div>
            <div class="col ps-0">
                <div class="col-12 px-4 pt-4 bg-white rounded-4 shadow-1">
                    <div class="row">
                        <div class="col-12 text-label-2 text-gray-10">
                            ${comentario?.usuario?.nombre_completo || ''}
                        </div>
                        <div class="col-12 text-body-3 comentario-contenido">
                            ${elemento_temporal.innerHTML}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    `;
}

/**
 * Enviar un comentario en la sección de comentarios de la prueba técnica.
 *
 * @param {number} etapa_vacante_usuario_id ID de la etapa vacante usuario.
 * @param {string} tipo_comentario Tipo de comentario (prueba_tecnica o videoentrevista)
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Andres Gonzalez
 */
function enviarComentario(etapa_vacante_usuario_id, tipo_comentario) {
    let comentario = obtenerDatosClassicEditor(`comentario_${tipo_comentario}`);
    if (comentario.trim() === '') {
        mostrarToast('warning', 'Debes escribir un comentario.');
        return;
    }
    establecerDatosClassicEditor(`comentario_${tipo_comentario}`, '');
    $.ajax({
        url: `/etapas-usuarios-comentarios`,
        type: 'POST',
        dataType: 'json',
        data: {
            _token: $('meta[name="csrf-token"]').attr('content'),
            etapa_vacante_usuario_id: etapa_vacante_usuario_id,
            comentario: limpiarHTMLCKEditor(comentario),
        },
        success: function(respuesta) {
            mostrarToast('success', 'Comentario enviado correctamente.');
            $.ajax({
                url: `/etapas-usuarios-comentarios`,
                type: 'GET',
                data: {
                    etapa_vacante_usuario_id: etapa_vacante_usuario_id,
                },
                dataType: 'json',
                success: function(datos) {
                    let comentarios = datos.data;
                    $(`#seccion-comentarios-${tipo_comentario}`).empty().append(mostrarSeccionComentarios(comentarios, tipo_comentario));
                },
                error: function() {
                    mostrarToast('danger', 'Error al cargar los comentarios.');
                }
            });

