function mostrarDetalleHojaVida(candidato) {
    let perfil = candidato?.perfil_laboral_completo || {};
    let estudios = perfil?.estudios || [];
    let experiencias = perfil?.experiencias_laborales || [];
    let idiomas = perfil?.idiomas || [];
    let preferencias = perfil?.preferencia_laboral || {};
    let conocimientos = perfil?.conocimiento_disponibilidad || {};

    let estudios_ordenados = estudios.sort((actual, siguiente) => {
        let fecha_actual = actual.fecha_fin || actual.fecha_inicio || '';
        let fecha_siguiente = siguiente.fecha_fin || siguiente.fecha_inicio || '';
        return new Date(fecha_siguiente) - new Date(fecha_actual);
    });

    let experiencias_ordenadas = experiencias.sort((actual, siguiente) => {
        let fecha_actual = actual.fecha_fin || actual.fecha_inicio || '';
        let fecha_siguiente = siguiente.fecha_fin || siguiente.fecha_inicio || '';
        return new Date(fecha_siguiente) - new Date(fecha_actual);
    });

    let nivel_educativo_html = estudios_ordenados.length > 0 ? estudios_ordenados.map(estudio => `
        <div class="col-12 py-3 px-4 border rounded-3 mb-3">
            <div class="row">
                <div class="col">
                    <p class="mb-1 fw-bold text-gray-20">${estudio.titulo || ''}</p>
                    <p class="text-body-3 mb-1">
                        ${estudio.fecha_inicio || estudio.fecha_fin ? `<i class="bi bi-calendar4 text-headline-5 me-2"></i>` : ''}
                        ${estudio.fecha_inicio ? moment(estudio.fecha_inicio).format("MMM YYYY") : ''}
                        ${estudio.fecha_inicio && !estudio.fecha_fin ? ' - Actualmente' : (estudio.fecha_fin ? ` - ${moment(estudio.fecha_fin).format("MMM YYYY")}` : '')}
                    </p>

